CREATE TABLE cosmetic_ownership ( uid TEXT NOT NULL, environment TEXT NOT NULL CHECK(environment IN ('sandbox','production')), item_id TEXT NOT NULL, acquired_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(uid,environment,item_id) );
CREATE TABLE cosmetic_purchases ( uid TEXT NOT NULL, environment TEXT NOT NULL CHECK(environment IN ('sandbox','production')), operation_id TEXT NOT NULL, item_id TEXT NOT NULL, expected_price INTEGER NOT NULL, charged INTEGER NOT NULL CHECK(charged >= 0), allocations TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(uid,environment,operation_id) );
